// Fetch major version; pure function, no side effects.
__u32 maj = libbpf_major_version();
// Best-effort sanity: value is an integer; no strict property guaranteed.
(void)maj;
// Validation: pure call executed without needing inputs/outputs.

// Fetch minor version; pure function, no side effects.
__u32 minv = libbpf_minor_version();
(void)minv;
// Validation: pure call executed without needing inputs/outputs.

// Retrieve static version string.
const char *ver = libbpf_version_string();
// API guarantees static storage; assert non-NULL pointer.
FUZZ_ASSERT(ver != NULL, "libbpf_version_string() returned NULL");
// Do not free or modify.
(void)ver;
// Validation: verifies non-NULL static pointer and avoids ownership issues.

// Generate an error code and a writable buffer, size in [1, 1024].
int err = *FUZZ_PARAM(int);
size_t sz = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
std::string buf; buf.resize(sz);
int rc = libbpf_strerror(err, buf.data(), sz);
// Acceptable outcomes: 0 on success, negative on error.
if (rc > 0) { FUZZ_BAIL(); }
// Validation: provides a valid writable buffer and enforces size contract.

// Cast a fuzzed integer to enum bpf_attach_type; function tolerates unknowns.
enum bpf_attach_type t = (enum bpf_attach_type)(*FUZZ_PARAM(unsigned int));
const char *s = libbpf_bpf_attach_type_str(t);
// Returned pointer may be NULL for unknown values; don't assert.
(void)s;
// Validation: exercises both known/unknown branches without ownership issues.

enum bpf_link_type t = (enum bpf_link_type)(*FUZZ_PARAM(unsigned int));
const char *s = libbpf_bpf_link_type_str(t);
(void)s;
// Validation: safe call; returned pointer may be NULL.

enum bpf_map_type t = (enum bpf_map_type)(*FUZZ_PARAM(unsigned int));
const char *s = libbpf_bpf_map_type_str(t);
(void)s;
// Validation: safe call; returned pointer may be NULL.

enum bpf_prog_type t = (enum bpf_prog_type)(*FUZZ_PARAM(unsigned int));
const char *s = libbpf_bpf_prog_type_str(t);
(void)s;
// Validation: safe call; returned pointer may be NULL.

// Set print callback to NULL (disable printing) and get previous callback.
// Passing NULL is explicitly allowed and thread-safe per API.
libbpf_print_fn_t prev = libbpf_set_print(NULL);
(void)prev; // not persisted to avoid storing function pointers in the pool
// Validation: exercises setter with NULL; avoids lifetime issues for callbacks.

// Open a BPF object from a fuzz-provided filename filled with random data.
const char *path = FUZZ_PARAM_FILENAME();
struct bpf_object *obj = bpf_object__open(path);
if (!obj) { FUZZ_BAIL(); }
// Track that object has been opened and is now valid for further API usage.
FUZZ_SET_ATTR_INT(obj, "opened", 1);
// Validation: ensures non-NULL result and records opened state.

const char *path = FUZZ_PARAM_FILENAME();
// Build options with valid sz and a small writable kernel log buffer.
struct bpf_object_open_opts opts = {};
opts.sz = sizeof(struct bpf_object_open_opts);
// Optionally set some fields from fuzzed data (remain valid for call lifetime).
std::string oname = FUZZ_PARAM_STR();
std::string pin_root = FUZZ_PARAM_STR();
std::string klog; klog.resize((size_t)(*FUZZ_PARAM(unsigned int) % 512u));
opts.object_name = oname.c_str();
opts.pin_root_path = pin_root.c_str();
opts.kernel_log_buf = klog.empty() ? NULL : klog.data();
opts.kernel_log_size = klog.size();
opts.kernel_log_level = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u);
struct bpf_object *obj = bpf_object__open_file(path, &opts);
if (!obj) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(obj, "opened", 1);
// Validation: opts->sz set, writable log buffer provided, object persisted on success.

// Provide an in-memory ELF buffer; random bytes may exercise error paths.
std::string blob = FUZZ_PARAM_STR();
// Randomly decide whether to pass opts or NULL.
bool use_opts = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
struct bpf_object_open_opts opts = {};
const struct bpf_object_open_opts *optsp = NULL;
if (use_opts) {
    opts.sz = sizeof(struct bpf_object_open_opts);
    std::string klog; klog.resize((size_t)(*FUZZ_PARAM(unsigned int) % 256u));
    opts.kernel_log_buf = klog.empty() ? NULL : klog.data();
    opts.kernel_log_size = klog.size();
    optsp = &opts;
}
struct bpf_object *obj = bpf_object__open_mem((const void *)blob.data(), blob.size(), optsp);
if (!obj) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(obj, "opened", 1);
// Validation: enforces opts->sz when provided and persists opened object.

// Ensure object was opened before prepare.
if (FUZZ_GET_ATTR_INT(obj, "opened") == 0) { FUZZ_BAIL(); }
int rc = bpf_object__prepare(obj);
if (rc < 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(obj, "prepared", 1);
// Validation: precondition (opened) enforced; success recorded for downstream usage.

// Prefer calling after prepare; allow if only opened as libbpf can handle.
int opened = FUZZ_GET_ATTR_INT(obj, "opened");
if (opened == 0) { FUZZ_BAIL(); }
int rc = bpf_object__load(obj);
if (rc < 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(obj, "loaded", 1);
// Validation: requires opened object, asserts successful load, and marks loaded state.

// Close and free all resources; obj may be NULL per API, but pool guarantees non-NULL.
